def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]

    opp_c = opp.count('C')
    opp_rate = opp_c / n

    recent_len = min(10, n)
    recent_opp = opp[-recent_len:]
    recent_me = me[-recent_len:]
    recent_opp_c = recent_opp.count('C')

    run_d = 0
    for x in reversed(opp):
        if x == 'D':
            run_d += 1
        else:
            break
    run_my_d = 0
    for x in reversed(me):
        if x == 'D':
            run_my_d += 1
        else:
            break

    if opp[-1] == 'D':
        if me[-1] == 'C':
            if opp_rate > 0.8 and run_d == 1:
                return 'C'
            if n >= 2 and me[-2] == 'D' and opp[-2] == 'D':
                return 'C'
            return 'D'
        else:
            if run_d >= 3 and run_my_d >= 2:
                return 'C'
            return 'D'
    else:
        if me[-1] == 'D':
            if n >= 2 and opp[-2] == 'C':
                return 'D'
            return 'C'
        else:
            if n >= 2 and me[-2] == 'D' and opp[-2] == 'C':
                return 'D'
            if n < 95 and opp_rate > 0.8 and recent_opp_c == recent_len:
                if rng.random() < 0.08:
                    return 'D'
            return 'C'
